INSERT INTO `services` (`id`, `created_by`, `kind`, `name`, `description`, `price`, `weekend_price`, `additional_head_weekday_price`, `additional_head_weekend_price`, `weekday_discount_type`, `weekday_discount_value`, `weekend_discount_type`, `weekend_discount_value`, `pax`, `features`, `amenities`, `status`, `created_at`, `updated_at`) VALUES
	(3, 1, 'room', 'Room 1', 'Provides a cozy bunk-style setup with air conditioning, a TV, and a private CR, great for small groups and families.', 3000.00, 3000.00, 50.00, 100.00, 'fixed', 500.00, NULL, NULL, 4, '[]', '["TV", "Private CR", "Airconditioned"]', 'active', '2026-11-10 09:35:31', '2026-11-16 06:49:58'),
	(5, NULL, 'exclusive', 'The Whole Villa', 'Make the whole beach house yours. Gather in the shared spaces, unwind in comfortable rooms, and enjoy an easygoing seaside stay with your group.', 15500.00, 17000.00, 50.00, 100.00, 'fixed', 1500.00, NULL, NULL, 35, '[]', '["TV", "Private CR", "Airconditioned", "2 Fans"]', 'active', '2026-11-11 20:47:31', '2026-11-16 06:49:58'),
	(6, 1, 'room', 'Room 2', 'Offers rustic wooden bunk beds and modern comforts, including AC, TV and a private CR, for a relaxing stay with your family and barkada.', 3000.00, 3000.00, 50.00, 100.00, 'fixed', 500.00, NULL, NULL, 4, '[]', '["TV", "Private CR", "Airconditioned"]', 'active', '2026-11-12 07:38:25', '2026-11-16 06:49:58'),
	(7, 1, 'room', 'Room 3', 'Offers rustic wooden bunk beds and modern comforts, including AC, TV and a private CR, for a relaxing stay with your family and barkada.', 3000.00, 3000.00, 50.00, 100.00, 'fixed', 500.00, NULL, NULL, 4, '[]', '["TV", "Private CR", "Airconditioned"]', 'active', '2026-11-12 07:44:13', '2026-11-16 06:49:58'),
	(8, 1, 'room', 'Room 4', 'Offers warm wooden bunk beds and air-conditioned comfort, an ideal pick for guest who wants a simple, peaceful retreat without the extras.', 4000.00, 4000.00, 50.00, 100.00, 'fixed', 500.00, NULL, NULL, 10, '[]', '["Airconditioned"]', 'active', '2026-11-12 07:46:24', '2026-11-16 06:49:58'),
	(9, 1, 'room', 'Room 5', 'Features  spacious ,comfty bed with airconditioning and two fans, giving you budget-friendly comfort and a relaxing, easygoing stay.', 4000.00, 4000.00, 50.00, 100.00, 'fixed', 500.00, NULL, NULL, 10, '[]', '["Airconditioned", "2 Fans"]', 'active', '2026-11-12 07:49:01', '2026-11-16 06:49:58');
